import { text, type Localized } from "../i18n";
import type { ExperienceCase, ExperienceImage } from "./types";

const image = (name: string, caption: Localized, contextual = false, credit?: string): ExperienceImage => ({
  src: `/images/experience/${name}.webp`, alt: caption, caption, contextual, credit,
});
const archive = (name: string, caption: Localized): ExperienceImage => ({
  src: `/images/projects/${name}.webp`, alt: caption, caption,
});
const series = (prefix: string, count: number, caption: Localized) =>
  Array.from({ length: count }, (_, index) => archive(`${prefix}-${index + 1}`, text(`${caption.es} · ${index + 1}`, `${caption.en} · ${index + 1}`)));
const fact = (label: Localized, value: Localized) => ({ label, value });

